import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.DYYBR_aZ.js";const p=JSON.parse('{"title":"工具使用","description":"开发工具的实用笔记与效率技巧","frontmatter":{"title":"工具使用","description":"开发工具的实用笔记与效率技巧"},"headers":[],"relativePath":"tools/index.md","filePath":"tools/index.md"}'),o={name:"tools/index.md"};function r(n,a,s,d,c,h){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="工具使用" tabindex="-1">工具使用 <a class="header-anchor" href="#工具使用" aria-label="Permalink to &quot;工具使用&quot;">​</a></h1><p>工具的价值不只是“会用”，更在于把重复操作变成稳定、高效的工作流。这里收录开发中常用工具的核心用法、快捷键和排错经验。</p><h2 id="内容导航" tabindex="-1">内容导航 <a class="header-anchor" href="#内容导航" aria-label="Permalink to &quot;内容导航&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">正在持续更新</p><p>这是一个新主题。后续可以将每类工具拆分为独立文章，通过左侧目录快速访问。</p></div><h3 id="git-与团队协作" tabindex="-1">Git 与团队协作 <a class="header-anchor" href="#git-与团队协作" aria-label="Permalink to &quot;Git 与团队协作&quot;">​</a></h3><ul><li>常用命令与分支管理</li><li>提交信息规范</li><li>冲突处理与历史回溯</li></ul><h3 id="docker-与开发环境" tabindex="-1">Docker 与开发环境 <a class="header-anchor" href="#docker-与开发环境" aria-label="Permalink to &quot;Docker 与开发环境&quot;">​</a></h3><ul><li>镜像、容器与数据卷</li><li>Docker Compose 本地编排</li><li>常见故障排查</li></ul><h3 id="ide-与命令行" tabindex="-1">IDE 与命令行 <a class="header-anchor" href="#ide-与命令行" aria-label="Permalink to &quot;IDE 与命令行&quot;">​</a></h3><ul><li>IntelliJ IDEA / VS Code 效率技巧</li><li>PowerShell 与 Shell 常用操作</li><li>环境配置与快捷键</li></ul><h2 id="推荐的笔记结构" tabindex="-1">推荐的笔记结构 <a class="header-anchor" href="#推荐的笔记结构" aria-label="Permalink to &quot;推荐的笔记结构&quot;">​</a></h2><p>每篇工具笔记可以按照以下顺序整理：</p><ol><li><strong>解决什么问题</strong>：先说明适用场景。</li><li><strong>最小可用步骤</strong>：给出可直接复现的操作。</li><li><strong>常用参数与示例</strong>：保留最实用的部分。</li><li><strong>易错点</strong>：记录真实遇到过的问题和解法。</li></ol>',13)])])}const _=e(o,[["render",r]]);export{p as __pageData,_ as default};
